package com.bananalab.lite;
import java.util.regex.*;
final class DialogueCommands{
 static CreatorSession.Result apply(String input,SceneDraft base)throws Exception{
  String q=ChatLanguage.normalize(input);Matcher voice=Pattern.compile("(?:cambia |pone )?(?:la )?voz (?:de )?(.+?) (?:a |en )?(grave|media|aguda|robotica)").matcher(q);Matcher length=Pattern.compile("(?:hace que dure|duracion|video de|que dure|pone la duracion en) ([0-9]{1,3}) (?:segundos|segundo|s)").matcher(q);
  if(voice.matches()||length.matches()){if(base==null)return CreatorSession.say("Primero creá una escena.");SceneDraft d=base.copy();if(voice.matches()){SceneDraft.Actor a=ScenePlanner.resolve(d,voice.group(1),false);if(a==null)return CreatorSession.say("Nombrá al personaje de esa voz.");a.voice=voice.group(2);d.focused=a.name;}else{int sec=Integer.parseInt(length.group(1));if(sec<3||sec>SceneTiming.MAX_SECONDS)return CreatorSession.say("Elegí una duración entre3 y120 segundos.");d.beatSeconds=sec/(float)ObjectTransfer.beats(d);d.fixedDuration=true;}try{SceneTiming.fit(d);}catch(Exception e){return CreatorSession.say(e.getMessage()+" Conservé la escena anterior.");}return new CreatorSession.Result(true,voice.matches()?"Actualicé la voz sintética experimental del personaje.":"Ajusté la duración a "+length.group(1)+" segundos.",d);}
  if(q.matches("quita los dialogos|borra los dialogos")){if(base==null)return CreatorSession.say("No hay una escena.");SceneDraft d=base.copy();d.dialogue.clear();return new CreatorSession.Result(true,"Quité las frases habladas; conservé las acciones.",d);}
  boolean quoted=input.matches("(?s).*\\b(?:dice|diga)\\s*[: ]\\s*[\"“].*");Matcher single=Pattern.compile("^(.+?) (?:dice|diga) (?![\"“])(.{1,120})$",Pattern.CASE_INSENSITIVE|Pattern.DOTALL).matcher(input.trim());if(!quoted&&!single.matches())return null;if(base==null)return CreatorSession.say("Primero creá los personajes que van a hablar.");SceneDraft d=base.copy();int slot=d.actions.isEmpty()?0:ObjectTransfer.beats(d);int added=0;
  if(quoted){Matcher line=Pattern.compile("(.+?) (?:dice|diga)\\s*[: ]\\s*[\"“]([^\"“”]{1,120})[\"”](?:\\s*(?:;|\\n)\\s*|$)",Pattern.CASE_INSENSITIVE).matcher(input.trim());int at=0;while(line.find()){if(line.start()!=at)return CreatorSession.say("Separá las frases como: Tony dice \"Hola\"; Milo dice \"Hola Tony\". No apliqué cambios.");String issue=add(d,line.group(1),line.group(2),slot++);if(issue!=null)return CreatorSession.say(issue);added++;at=line.end();}if(at!=input.trim().length()||added==0)return CreatorSession.say("No pude separar todos los diálogos; conservé la escena anterior.");}
  else{String issue=add(d,single.group(1),single.group(2),slot);if(issue!=null)return CreatorSession.say(issue);added=1;}
  d.sound=true;try{SceneTiming.fit(d);SceneConsistency.require(d);}catch(Exception e){return CreatorSession.say(e.getMessage()+" Conservé la escena anterior.");}return new CreatorSession.Result(true,"Agregué "+added+" frase"+(added==1?" hablada":"s habladas")+" con voz sintética propia y boca sincronizada en los diseños generados. Las referencias conservan su imagen. La voz es experimental y robótica.",d);
 }
 static String add(SceneDraft d,String who,String text,int slot){if(!text.matches("[a-zA-ZáéíóúüñÁÉÍÓÚÜÑ ,;:.!?¿¡'-]+"))return "La voz propia experimental admite texto en español sin números ni símbolos. Escribí los números con palabras; no apliqué cambios.";SceneDraft.Actor a=ScenePlanner.resolve(d,ChatLanguage.normalize(who),false);if(a==null)return "Nombrá un único personaje para cada frase. No apliqué cambios.";if(slot>=SceneTiming.MAX_BEATS||d.actions.size()>=SceneTiming.MAX_ACTIONS||d.dialogue.size()>=32)return "No queda espacio para más diálogos en esta toma.";SceneDirector.step(d,a,"habla",slot,"","");d.dialogue.add(new SceneDraft.Line(a.name,slot,text.trim()));d.focused=a.name;return null;}
 static float mouth(SceneDraft d,String actor,float time){float second=time*SceneTiming.seconds(d);for(SceneDraft.Line line:d.dialogue)if(line.actor.equals(actor)){SceneDraft.Actor a=d.get(actor);float local=second-line.slot*d.beatSeconds-.05f;if(local>=0&&local<VoiceSynth.duration(line.text,a.voice))return VoiceSynth.mouth(line.text,a.voice,local);}return 0;}
 static boolean hasLine(SceneDraft d,String actor,int slot){for(SceneDraft.Line l:d.dialogue)if(l.actor.equals(actor)&&l.slot==slot)return true;return false;}
}
